/* ====================================
   JFSN Filter Container - Complete JavaScript
   ==================================== */

// Global variables for filter functionality
window.galleryData = [];
let galleryData = window.galleryData;
let visibleItems = 20; // Number of items to render initially
let currentPage = 0;
let isLoading = false;

// Load metadata from JSON file
async function loadMetadata() {
  try {
    console.log('📁 Loading metadata.json...');
    const response = await fetch('index/metadata.json');
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    const metadata = await response.json();
    
    // Transform metadata to match gallery data format using .avif thumbs
    window.galleryData = metadata.map((item, index) => {
      // Extract artwork number from filename (e.g., art0001.avif from art0001_compressed.jpeg)
      let artworkNumber = '';
      if (item.file) {
        const match = item.file.match(/art(\d{4})/);
        if (match) {
          artworkNumber = match[1]; // Gets the 4-digit number
        }
      }
      
      const avifPath = artworkNumber ? `artworks/thumbs/art${artworkNumber}.avif` : 'data:image/svg+xml;base64,';
      
      return {
        id: index + 1,
        title: item.title || `Artwork ${artworkNumber || item.file}`,
        category: item.category || 'Misc',
        tags: item.keywords || [],
        keywords: item.keywords || [],
        image: avifPath,
        description: item.description || 'No description available',
        extended_description: item.extended_description || item.description || 'No description available',
        file: item.file,
        artworkNumber: artworkNumber,
        year: 2024, // Default year, could be extracted from metadata if available
        featured: false
      };
    });
    
    console.log(`✅ Loaded ${window.galleryData.length} artworks from metadata`);
    console.log('📊 Categories found:', [...new Set(window.galleryData.map(item => item.category))]);
    console.log('🎯 Total artworks loaded:', window.galleryData.length);
    
    // Preload image dimensions for dimension-based filtering
    await preloadImageDimensions();
    
    // Initialize intersection observer for lazy loading
    initLazyLoading();
    
    // Verify the count is correct
    if (window.galleryData.length !== 1050) {
      console.warn('⚠️ Expected 1050 artworks but got:', window.galleryData.length);
    } else {
      console.log('✅ All 1050 artworks loaded successfully');
    }
    
    return window.galleryData;
  } catch (error) {
    console.error('❌ Error loading metadata:', error);
    return [];
  }
}

// Lazy loading with Intersection Observer
function initLazyLoading() {
  if ('IntersectionObserver' in window) {
    const imageObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const img = entry.target;
          if (img.dataset.src) {
            img.src = img.dataset.src;
            img.removeAttribute('data-src');
            img.loading = 'lazy';
            observer.unobserve(img);
          }
        }
      });
    }, {
      rootMargin: '100px 0px',
      threshold: 0.01
    });

    // Observe all images with data-src
    document.querySelectorAll('img[data-src]').forEach(img => {
      imageObserver.observe(img);
    });
  }
}

// Progressive loading - only load first 20 items initially
function loadInitialItems() {
  const initialItems = window.galleryData.slice(0, visibleItems);
  console.log(`📱 Loading initial ${visibleItems} items for mobile performance`);
  return initialItems;
}

// Load more items when user scrolls
function loadMoreItems() {
  if (isLoading) return;
  isLoading = true;
  
  const startIndex = currentPage * visibleItems;
  const endIndex = startIndex + visibleItems;
  const newItems = window.galleryData.slice(startIndex, endIndex);
  
  if (newItems.length > 0) {
    currentPage++;
    console.log(`📱 Loading more items: ${startIndex}-${endIndex}`);
    return newItems;
  }
  
  isLoading = false;
  return [];
}

// Function to detect image dimensions by loading actual images
function getImageDimensions(item) {
  // Extract artwork number from filename
  let artworkNumber = '';
  if (item.file) {
    const match = item.file.match(/art(\d{4})/);
    if (match) {
      artworkNumber = match[1];
    }
  } else if (item.title && /^\d{4}$/.test(item.title)) {
    artworkNumber = item.title;
  }
  
  if (!artworkNumber) return 'vertical'; // Default fallback
  
  // Create image path
  const paddedNum = artworkNumber.padStart(4, '0');
  const imagePath = `artworks/thumbs/art${paddedNum}.avif`;
  
  // Return a promise that resolves with the actual dimensions
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = function() {
      const aspectRatio = this.width / this.height;
      if (Math.abs(aspectRatio - 1) < 0.1) {
        resolve('square');
      } else if (aspectRatio > 1) {
        resolve('horizontal');
      } else {
        resolve('vertical');
      }
    };
    img.onerror = function() {
      // Fallback to vertical if image fails to load
      resolve('vertical');
    };
    img.src = imagePath;
  });
}

// Synchronous version for filtering (uses cached dimensions)
let dimensionCache = {};

function getCachedImageDimensions(item) {
  let artworkNumber = '';
  if (item.file) {
    const match = item.file.match(/art(\d{4})/);
    if (match) {
      artworkNumber = match[1];
    }
  } else if (item.title && /^\d{4}$/.test(item.title)) {
    artworkNumber = item.title;
  }
  
  if (!artworkNumber) return 'vertical';
  
  // Return cached dimension or 'vertical' as fallback
  return dimensionCache[artworkNumber] || 'vertical';
}

// Function to preload and cache image dimensions
async function preloadImageDimensions() {
  if (!window.galleryData) return;
  
  console.log('🖼️ Preloading image dimensions...');
  const promises = window.galleryData.map(async (item) => {
    const dimension = await getImageDimensions(item);
    let artworkNumber = '';
    if (item.file) {
      const match = item.file.match(/art(\d{4})/);
      if (match) {
        artworkNumber = match[1];
      }
    } else if (item.title && /^\d{4}$/.test(item.title)) {
      artworkNumber = item.title;
    }
    
    if (artworkNumber) {
      dimensionCache[artworkNumber] = dimension;
    }
  });
  
  await Promise.all(promises);
  console.log('✅ Image dimensions cached:', dimensionCache);
}

// Filter gallery function
function filterGallery(query = '', category = 'all') {
  console.log('🔍 Filtering gallery:', { query, category });
  
  const filteredData = window.galleryData.filter(item => {
    const matchesQuery = !query || 
      item.title.toLowerCase().includes(query.toLowerCase()) ||
      (item.keywords && item.keywords.some(keyword => 
        keyword.toLowerCase().includes(query.toLowerCase())
      ));
    
    let matchesCategory = false;
    
    if (category === 'all') {
      matchesCategory = true;
    } else if (category === 'featured') {
      const itemId = item.id || '';
      matchesCategory = itemId === '1009' || itemId === '1010' || 
                      item.title.toLowerCase().includes('featured artwork 1009') || 
                      item.title.toLowerCase().includes('featured artwork 1010');
    } else if (category === 'favorites') {
      // Check if item is in localStorage favorites
      const favorites = JSON.parse(localStorage.getItem('artworkFavorites') || '[]');
      matchesCategory = favorites.includes(item.id.toString());
    } else if (category === 'new') {
      // Check if item is in "New" category
      matchesCategory = item.category && item.category.toLowerCase() === 'new';
    } else if (['vertical', 'horizontal', 'square'].includes(category)) {
      // Handle dimension-based filtering
      const itemDimension = getCachedImageDimensions(item);
      matchesCategory = itemDimension === category;
    } else {
      matchesCategory = item.category && 
        item.category.toLowerCase() === category.toLowerCase();
    }
    
    return matchesQuery && matchesCategory;
  });

  console.log('📊 Filtered results:', filteredData.length, 'items');
  
  // Emit filtered results
  const event = new CustomEvent('galleryFiltered', {
    detail: { filteredData, query, category }
  });
  document.dispatchEvent(event);
  
  return filteredData;
}

// Generate filter chips based on categories
function generateFilterChips() {
  const filterSection = document.getElementById('filterSection');
  if (!filterSection) {
    console.error('❌ Filter section not found');
    return;
  }

  // Get unique categories from gallery data (exclude 'New' since it has its own chip)
  const categories = [...new Set(window.galleryData.map(item => item.category))].filter(cat => cat !== 'New');
  console.log('📊 Categories for filter chips:', categories);

  // Create "PICK A FILTER >" as first chip (non-interactive)
  const labelChip = document.createElement('div');
  labelChip.className = 'filter-chip filter-label-chip';
  labelChip.innerHTML = `<span class="filter-text">PICK A FILTER ></span>`;
  filterSection.appendChild(labelChip);

  // Create "All" filter chip
  const allChip = document.createElement('div');
  allChip.className = 'filter-chip active';
  allChip.setAttribute('data-category', 'all');
  allChip.innerHTML = `
    <span class="filter-text">All</span>
    <span class="filter-count">${window.galleryData.length}</span>
  `;
  allChip.addEventListener('click', () => {
    // Remove active class from all chips
    document.querySelectorAll('.filter-chip').forEach(chip => {
      chip.classList.remove('active');
    });
    // Add active class to clicked chip
    allChip.classList.add('active');
    filterGallery('', 'all');
  });
  filterSection.appendChild(allChip);

  // Create New filter chip
  const newCount = window.galleryData.filter(item => 
    item.category && item.category.toLowerCase() === 'new'
  ).length;
  
  const newChip = document.createElement('div');
  newChip.className = 'filter-chip';
  newChip.setAttribute('data-category', 'new');
  newChip.innerHTML = `
    <span class="filter-text">New</span>
    <span class="filter-count">${newCount}</span>
  `;
  newChip.addEventListener('click', () => {
    console.log('New filter chip clicked!');
    // Remove active class from all chips
    document.querySelectorAll('.filter-chip').forEach(chip => {
      chip.classList.remove('active');
    });
    // Add active class to clicked chip
    newChip.classList.add('active');
    filterGallery('', 'new');
  });
  filterSection.appendChild(newChip);

  // Create Favorites filter chip
  const favorites = JSON.parse(localStorage.getItem('artworkFavorites') || '[]');
  const favoritesCount = window.galleryData.filter(item => 
    favorites.includes(item.id.toString())
  ).length;
  
  const favoritesChip = document.createElement('div');
  favoritesChip.className = 'filter-chip';
  favoritesChip.setAttribute('data-category', 'favorites');
  favoritesChip.innerHTML = `
    <span class="filter-text">Favorites</span>
    <span class="filter-count">${favoritesCount}</span>
  `;
  favoritesChip.addEventListener('click', () => {
    // Remove active class from all chips
    document.querySelectorAll('.filter-chip').forEach(chip => {
      chip.classList.remove('active');
    });
    // Add active class to clicked chip
    favoritesChip.classList.add('active');
    filterGallery('', 'favorites');
  });
  filterSection.appendChild(favoritesChip);

  // Create category filter chips
  categories.forEach(category => {
    const count = window.galleryData.filter(item => item.category === category).length;
    const chip = document.createElement('div');
    chip.className = 'filter-chip';
    chip.setAttribute('data-category', category);
    chip.innerHTML = `
      <span class="filter-text">${category}</span>
      <span class="filter-count">${count}</span>
    `;
    chip.addEventListener('click', () => filterGallery('', category));
    filterSection.appendChild(chip);
  });

  // Create dimension-based filter chips
  const dimensions = ['vertical', 'horizontal', 'square'];
  dimensions.forEach(dimension => {
    const count = window.galleryData.filter(item => getCachedImageDimensions(item) === dimension).length;
    const chip = document.createElement('div');
    chip.className = 'filter-chip';
    chip.setAttribute('data-category', dimension);
    chip.innerHTML = `
      <span class="filter-text">${dimension.charAt(0).toUpperCase() + dimension.slice(1)}</span>
      <span class="filter-count">${count}</span>
    `;
    chip.addEventListener('click', () => filterGallery('', dimension));
    filterSection.appendChild(chip);
  });

  console.log(`✅ Generated ${categories.length + 1 + dimensions.length} filter chips`);
}

// Function to refresh favorites count
function refreshFavoritesCount() {
  const favoritesChip = document.querySelector('[data-category="favorites"]');
  if (favoritesChip) {
    const favorites = JSON.parse(localStorage.getItem('artworkFavorites') || '[]');
    const favoritesCount = window.galleryData.filter(item => 
      favorites.includes(item.id.toString())
    ).length;
    
    const countElement = favoritesChip.querySelector('.filter-count');
    if (countElement) {
      countElement.textContent = favoritesCount;
    }
  }
}

// Make refreshFavoritesCount globally accessible
window.refreshFavoritesCount = refreshFavoritesCount;

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
  console.log('🚀 Initializing JFSN Filter System...');
  
  // Load metadata first
  loadMetadata().then(() => {
    console.log('✅ Filter system initialized successfully');
    generateFilterChips();
  });
});
